function repeatsName(entries: readonly TreeEntry[]): boolean {
	return new Set(entries.map((entry) => entry.path.toString("latin1"))).size !== entries.length;
}

async retire(seen: ReadonlyMap<string, string>, merged: ReadonlySet<string>): Promise<Retirement> {
	if (this.#closed) throw new RecordError("closed", "the record store is closed");
	for (const changeset of seen.keys()) checkChangeset(changeset);
	return this.#land(async (tip, deadline) => {
		const folders =
			tip === undefined ? new Map<string, string>() : await StateTree.folders(this.#repository, tip, deadline);
		const value = {
			removed: [] as string[],
			kept: [] as string[],
			changed: [] as string[],
			strays: [] as string[],
			absent: [] as string[],
			deferred: [] as string[],
		};
		// A call's own judgements and totals, so what it holds stays within one call's limits and outlives it in nothing.
		const judged = new Map<string, Judged>();
		const spent = { entries: 0, bytes: 0 };
		for (const [changeset, oid] of seen) {
			const now = folders.get(changeset);
			if (now === undefined) value.absent.push(changeset);
			else if (now !== oid) value.changed.push(changeset);
			else if (!merged.has(changeset)) value.kept.push(changeset);
			else if (value.deferred.length > 0) value.deferred.push(changeset);
			else {
				const verdict = await StateTree.judgeFolder(this.#repository, changeset, now, judged, spent, deadline);
				value[verdict === "clean" ? "removed" : verdict === "stray" ? "strays" : verdict].push(changeset);
			}
		}
		if (tip === undefined || value.removed.length === 0) return { value };
		const commit = await this.#repository.withoutFolders(tip, value.removed, deadline);
		if (!(await StateTree.removesOnly(this.#repository, tip, commit, deadline)))
			throw new RecordError(
				"unreachable",
				`the commit retiring ${value.removed.join(", ")} changes more of ${this.#branch} than it removes; nothing was pushed`,
			);
		return { commit, value };
	});

// Whether `commit` has `parent` as its one parent and `parent`'s tree with only whole `changesets/<name>` folders
// removed, at least one: each other root entry and each kept folder the same by name, mode, type and object ID, as
// `ls-tree` lists them, and no name listed twice in the parent's `changesets/`.
static async removesOnly(
	repository: RecordRepository,
	parent: string,
	commit: string,
	deadline: Deadline,
): Promise<boolean> {
	const parents = await repository.parents(commit, deadline);
	if (parents.length !== 1 || parents[0] !== parent) return false;
	const before = await repository.children(parent, deadline, listingLimit);
	const after = await repository.children(commit, deadline, listingLimit);
	if (before === undefined || after === undefined) return false;
	const was = before.find(isChangesets);
	const now = after.find((entry) => entry.path.toString("latin1") === changesetsName);
	if (was === undefined || (now !== undefined && now.type !== "tree")) return false;
	if (
		!sameEntries(
			before.filter((entry) => entry !== was),
			after.filter((entry) => entry !== now),
		)
	)
		return false;
	const folders = await repository.children(was.oid, deadline, listingLimit);
	const kept = now === undefined ? [] : await repository.children(now.oid, deadline, listingLimit);
	if (folders === undefined || kept === undefined || kept.length >= folders.length) return false;
	if (repeatsName(folders)) return false;
	const held = new Set(folders.map(keyOf));
	const left = new Set(kept.map(keyOf));
	return (
		kept.every((entry) => held.has(keyOf(entry))) &&
		folders.every((entry) => left.has(keyOf(entry)) || folderName(entry) !== undefined)
	);
}
